export const motionTokens = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    standard: 0.24,
    considered: 0.48,
    reveal: 0.6,
    lineReveal: 0.86,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1],
    standard: [0.22, 1, 0.36, 1],
  },
  spring: {
    snappy: { type: "spring", visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring", visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring", visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { item: 0.035, character: 0.025, word: 0.075, line: 0.08 },
  blur: { subtle: 2 },
} as const;

"use client";

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { IconMorph, type IconMorphPaths } from "../icon-morph/icon-morph";
import { motionTokens } from "../lib/motion-tokens";
import { MorphingText } from "../morphing-text/morphing-text";
import "../foundation.css";

export type ButtonVariant = "filled" | "bordered" | "text";
export type ButtonTone = "primary" | "secondary" | "success" | "warning" | "danger";
export type ButtonSize = "small" | "medium" | "large";

const baseClass = "inline-flex w-fit items-center justify-center gap-2 whitespace-nowrap rounded-[18px] border font-[inherit] font-[650] leading-none no-underline transition-[opacity,background-color,border-color,color,transform] duration-[var(--duration-fast)] ease-[var(--ease-standard)] [webkit-tap-highlight-color:transparent] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-3 disabled:cursor-not-allowed disabled:opacity-[0.48] aria-disabled:cursor-not-allowed aria-disabled:opacity-[0.48] active:not-disabled:translate-y-px";

const sizeClasses: Record<ButtonSize, string> = {
  small: "min-h-10 px-4 text-xs",
  medium: "min-h-[46px] px-5 text-[13px]",
  large: "min-h-[52px] px-6 text-sm",
};

const appearanceClasses: Record<ButtonVariant, Record<ButtonTone, string>> = {
  filled: {
    primary: "border-transparent bg-[var(--primary)] text-[var(--primary-foreground)] hover:bg-[var(--primary-hover)]",
    secondary: "border-transparent bg-[var(--surface-muted)] text-[var(--text)] hover:bg-[color-mix(in_srgb,var(--surface-muted)_82%,var(--text))]",
    success: "border-transparent bg-[var(--surface-muted)] text-[var(--success-surface-foreground)] hover:bg-[var(--success-surface)]",
    warning: "border-transparent bg-[var(--surface-muted)] text-[var(--warning-surface-foreground)] hover:bg-[var(--warning-surface)]",
    danger: "border-transparent bg-[var(--surface-muted)] text-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
  },
  bordered: {
    primary: "border-[color-mix(in_srgb,var(--text)_75%,transparent)] bg-[color-mix(in_srgb,var(--surface-muted)_75%,transparent)] text-[var(--text)] hover:border-[var(--text)] hover:bg-[color-mix(in_srgb,var(--primary)_25%,transparent)]",
    secondary: "border-[color-mix(in_srgb,var(--text-secondary)_72%,transparent)] bg-[color-mix(in_srgb,var(--surface-muted)_75%,transparent)] text-[var(--text-secondary)] hover:border-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
    success: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--success-surface-foreground)] hover:border-[var(--success-surface-foreground)] hover:bg-[var(--success-surface)]",
    warning: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--warning-surface-foreground)] hover:border-[var(--warning-surface-foreground)] hover:bg-[var(--warning-surface)]",
    danger: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--danger-surface-foreground)] hover:border-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
  },
  text: {
    primary: "border-transparent bg-transparent text-[var(--text)] hover:bg-[var(--surface-muted)]",
    secondary: "border-transparent bg-transparent text-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
    success: "border-transparent bg-transparent text-[var(--success-surface-foreground)] hover:bg-[var(--surface-muted)]",
    warning: "border-transparent bg-transparent text-[var(--warning-surface-foreground)] hover:bg-[var(--surface-muted)]",
    danger: "border-transparent bg-transparent text-[var(--danger-surface-foreground)] hover:bg-[var(--surface-muted)]",
  },
};

function classes(variant: ButtonVariant, tone: ButtonTone, size: ButtonSize, className?: string) {
  return [baseClass, sizeClasses[size], appearanceClasses[variant][tone], className]
    .filter(Boolean)
    .join(" ");
}

interface ButtonStyleProps {
  variant?: ButtonVariant;
  tone?: ButtonTone;
  size?: ButtonSize;
}

type OneOrMany<Value> = Value | readonly Value[];

export interface ButtonProps
  extends Omit<ComponentPropsWithoutRef<"button">, "children"> {
  variant?: ButtonVariant;
  tone?: OneOrMany<ButtonTone>;
  size?: ButtonSize;
  children?: ReactNode;
  label?: OneOrMany<string>;
  icon?: OneOrMany<ReactNode>;
  iconPosition?: "start" | "end";
  loading?: OneOrMany<boolean>;
  state?: number;
  iconPaths?: IconMorphPaths;
}

function atState<Value>(value: OneOrMany<Value> | undefined, state: number) {
  if (value === undefined) return undefined;
  if (!Array.isArray(value)) return value as Value;
  return value[Math.min(state, value.length - 1)];
}

function ButtonIcon({ icons, state, paths, spinning }: {
  icons: OneOrMany<ReactNode>;
  state: number;
  paths?: IconMorphPaths;
  spinning?: boolean;
}) {
  const reduceMotion = useReducedMotion() ?? false;
  const values = Array.isArray(icons) ? icons : [icons];
  const current = values[Math.min(state, values.length - 1)];

  if (paths && values.length === 2) {
    return <IconMorph state={state > 0} from={values[0]} to={values[1]} paths={paths} size={18} />;
  }

  return (
    <span className="relative inline-grid size-[18px] place-items-center">
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          className="absolute inset-0 grid origin-center place-items-center"
          key={state}
          initial={{ opacity: 0, scale: reduceMotion ? 1 : 0.62 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: reduceMotion ? 1 : 0.62 }}
          transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
        >
          <motion.span
            className="grid place-items-center [&>svg]:size-[18px]"
            animate={{ rotate: spinning && !reduceMotion ? 360 : 0 }}
            transition={spinning && !reduceMotion
              ? { duration: 0.8, ease: "linear", repeat: Infinity }
              : { duration: 0 }}
          >
            {current}
          </motion.span>
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button({
  variant = "filled",
  tone = "primary",
  size = "medium",
  label,
  icon,
  iconPosition = "start",
  loading = false,
  state = 0,
  iconPaths,
  className,
  children,
  type = "button",
  ...props
}, ref) {
  const activeState = Math.max(0, Math.floor(state));
  const activeTone = atState(tone, activeState) ?? "primary";
  const isLoading = atState(loading, activeState) ?? false;
  const activeIcon = icon
    ? <ButtonIcon icons={icon} state={activeState} paths={iconPaths} spinning={isLoading} />
    : undefined;
  const content = label === undefined
    ? children
    : <MorphingText value={atState(label, activeState) ?? ""} />;
  const iconOnly = activeIcon !== undefined && content == null;

  return (
    <button
      ref={ref}
      {...props}
      type={type}
      aria-busy={isLoading || undefined}
      className={classes(variant, activeTone, size, [
        iconOnly && { small: "w-10 px-0", medium: "w-[46px] px-0", large: "w-[52px] px-0" }[size],
        className,
      ].filter(Boolean).join(" "))}
    >
      {activeIcon && iconPosition === "start" ? <span className="grid shrink-0 place-items-center" aria-hidden="true">{activeIcon}</span> : null}
      {content}
      {activeIcon && iconPosition === "end" ? <span className="grid shrink-0 place-items-center" aria-hidden="true">{activeIcon}</span> : null}
    </button>
  );
});

export interface ButtonLinkProps extends ComponentPropsWithoutRef<"a">, ButtonStyleProps {
  icon?: ReactNode;
  iconPosition?: "start" | "end";
}

export function ButtonLink({
  variant = "filled",
  tone = "primary",
  size = "medium",
  icon,
  iconPosition = "start",
  className,
  children,
  ...props
}: ButtonLinkProps) {
  return (
    <a {...props} className={classes(variant, tone, size, className)}>
      {icon && iconPosition === "start" ? <span className="grid shrink-0 place-items-center [&>svg]:size-[18px]" aria-hidden="true">{icon}</span> : null}
      {children}
      {icon && iconPosition === "end" ? <span className="grid shrink-0 place-items-center [&>svg]:size-[18px]" aria-hidden="true">{icon}</span> : null}
    </a>
  );
}

"use client";

import type { CSSProperties, ReactNode } from "react";
import { motion, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export interface IconMorphPaths {
  from: string[];
  to: string[];
}

export interface IconMorphProps {
  state: boolean;
  from: ReactNode;
  to: ReactNode;
  paths?: IconMorphPaths;
  size?: number;
  strokeWidth?: number;
  className?: string;
  style?: CSSProperties;
}

const pathCommands = (path: string) => path.match(/[a-z]/gi)?.join("") ?? "";
const pathValues = (path: string) =>
  path.match(/-?(?:\d*\.)?\d+(?:e[-+]?\d+)?/gi)?.length ?? 0;

function pathsCanMorph(paths?: IconMorphPaths) {
  if (!paths || paths.from.length === 0 || paths.from.length !== paths.to.length) {
    return false;
  }

  return paths.from.every(
    (path, index) =>
      pathCommands(path) === pathCommands(paths.to[index] ?? "") &&
      pathValues(path) === pathValues(paths.to[index] ?? ""),
  );
}

export const iconMorphPresets = {
  menuClose: {
    from: ["M4 7L20 7", "M4 12L20 12", "M4 17L20 17"],
    to: ["M6 6L18 18", "M12 12L12 12", "M18 6L6 18"],
  },
  plusCheck: {
    from: ["M12 5L12 19", "M5 12L19 12"],
    to: ["M5 13L10 18", "M10 18L19 7"],
  },
  playPause: {
    from: ["M7 5L12 8L12 16L7 19Z", "M12 8L19 12L12 16L12 8Z"],
    to: ["M7 5L11 5L11 19L7 19Z", "M14 5L18 5L18 19L14 19Z"],
  },
  chevron: {
    from: ["M6 9L12 15L18 9"],
    to: ["M9 6L15 12L9 18"],
  },
} satisfies Record<string, IconMorphPaths>;

export function IconMorph({
  state,
  from,
  to,
  paths,
  size = 24,
  strokeWidth = 1.75,
  className,
  style,
}: IconMorphProps) {
  const reduceMotion = useReducedMotion() ?? false;
  const canMorph = pathsCanMorph(paths);
  const rootStyle = {
    ...style,
    "--icon-morph-size": `${size}px`,
  } as CSSProperties;

  if (canMorph && paths) {
    return (
      <motion.svg
        className={["relative inline-grid size-[var(--icon-morph-size)] shrink-0 place-items-center align-middle text-[inherit]", className].filter(Boolean).join(" ")}
        style={rootStyle}
        viewBox="0 0 24 24"
        width={size}
        height={size}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        focusable="false"
      >
        {paths.from.map((path, index) => (
          <motion.path
            key={index}
            initial={false}
            animate={{ d: state ? paths.to[index] : path }}
            transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
          />
        ))}
      </motion.svg>
    );
  }

  const hidden = {
    opacity: 0,
    scale: reduceMotion ? 1 : 0.62,
  };
  const visible = { opacity: 1, scale: 1 };
  const transition = reduceMotion
    ? { duration: 0 }
    : {
        scale: motionTokens.spring.smooth,
        opacity: {
          duration: motionTokens.duration.fast,
          ease: motionTokens.ease.standard,
        },
      };

  return (
    <span
      className={["relative inline-grid size-[var(--icon-morph-size)] shrink-0 place-items-center align-middle text-[inherit]", className].filter(Boolean).join(" ")}
      style={rootStyle}
      aria-hidden="true"
    >
      <motion.span
        className="absolute inset-0 grid origin-center place-items-center will-change-[transform,opacity] motion-reduce:will-change-auto [&>svg]:size-full"
        initial={false}
        animate={state ? hidden : visible}
        transition={transition}
      >
        {from}
      </motion.span>
      <motion.span
        className="absolute inset-0 grid origin-center place-items-center will-change-[transform,opacity] motion-reduce:will-change-auto [&>svg]:size-full"
        initial={false}
        animate={state ? visible : hidden}
        transition={transition}
      >
        {to}
      </motion.span>
    </span>
  );
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import {
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
  type HTMLMotionProps,
} from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

type SpanProps = Omit<HTMLMotionProps<"span">, "children">;

export interface MorphingTextProps extends SpanProps {
  value: string;
}

interface TextDifference {
  prefix: string;
  previous: string;
  current: string;
  suffix: string;
}

function compareText(previous: string, current: string): TextDifference {
  const previousCharacters = Array.from(previous);
  const currentCharacters = Array.from(current);
  const sharedLength = Math.min(previousCharacters.length, currentCharacters.length);
  let prefixLength = 0;

  while (
    prefixLength < sharedLength &&
    previousCharacters[prefixLength] === currentCharacters[prefixLength]
  ) {
    prefixLength += 1;
  }

  let previousEnd = previousCharacters.length;
  let currentEnd = currentCharacters.length;

  while (
    previousEnd > prefixLength &&
    currentEnd > prefixLength &&
    previousCharacters[previousEnd - 1] === currentCharacters[currentEnd - 1]
  ) {
    previousEnd -= 1;
    currentEnd -= 1;
  }

  return {
    prefix: currentCharacters.slice(0, prefixLength).join(""),
    previous: previousCharacters.slice(prefixLength, previousEnd).join(""),
    current: currentCharacters.slice(prefixLength, currentEnd).join(""),
    suffix: currentCharacters.slice(currentEnd).join(""),
  };
}

export function MorphingText({
  value,
  className,
  style,
  ...props
}: MorphingTextProps) {
  const [change, setChange] = useState({ previous: value, current: value });
  const measureRef = useRef<HTMLSpanElement>(null);
  const firstMeasurement = useRef(true);
  const reduceMotion = useReducedMotion() ?? false;
  const width = useMotionValue(0);

  if (change.current !== value) {
    setChange({ previous: change.current, current: value });
  }

  const difference = compareText(change.previous, change.current);
  const changedText = difference.current;
  const hasChangedText = Boolean(difference.previous || changedText);

  useLayoutEffect(() => {
    const measure = measureRef.current;
    if (!measure) return;
    let stopAnimation = () => {};

    const resize = () => {
      const nextWidth = measure.getBoundingClientRect().width;
      stopAnimation();

      if (firstMeasurement.current || reduceMotion) {
        firstMeasurement.current = false;
        width.jump(nextWidth);
        return;
      }

      const controls = animate(width, nextWidth, motionTokens.spring.smooth);
      stopAnimation = () => controls.stop();
    };

    resize();
    const observer = new ResizeObserver(resize);
    observer.observe(measure);
    return () => {
      stopAnimation();
      observer.disconnect();
    };
  }, [changedText, reduceMotion, width]);

  return (
    <motion.span
      {...props}
      className={["relative inline-block whitespace-nowrap", className].filter(Boolean).join(" ")}
      style={style}
      aria-live="polite"
    >
      <span className="absolute size-px overflow-hidden [clip:rect(0,0,0,0)] [clip-path:inset(50%)] whitespace-nowrap">{value}</span>
      <span className="inline-flex items-baseline whitespace-nowrap" aria-hidden="true">
        <span className="whitespace-pre">{difference.prefix}</span>
        <motion.span className="relative inline-grid min-w-0 overflow-hidden text-start" style={{ width }}>
          {hasChangedText ? (
            <motion.span
              key={change.current}
              className="absolute top-0 left-0 flex w-max flex-col [line-height:inherit] will-change-transform"
              initial={{
                transform: reduceMotion ? "translateY(-50%)" : "translateY(0%)",
              }}
              animate={{ transform: "translateY(-50%)" }}
              transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
            >
              <span className="block h-[1lh] whitespace-pre">
                {difference.previous || "\u00a0"}
              </span>
              <span className="block h-[1lh] whitespace-pre">{changedText || "\u00a0"}</span>
            </motion.span>
          ) : null}
          <span className="col-[1] row-[1] invisible inline-block justify-self-start whitespace-pre pointer-events-none">{changedText || "\u00a0"}</span>
          <span ref={measureRef} className="absolute invisible w-max whitespace-pre pointer-events-none">
            {changedText}
          </span>
        </motion.span>
        <span className="whitespace-pre">{difference.suffix}</span>
      </span>
    </motion.span>
  );
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { CircleAlert, CircleCheck, CircleX, Info } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { Button } from "../button/button";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export type DialogTone = "neutral" | "success" | "warning" | "danger";
export type DialogActions = "confirm" | "close";

export interface DialogProps {
  /** Optional native interactive element that opens the dialog. */
  trigger?: ReactNode;
  /** Visible dialog heading. */
  title: ReactNode;
  /** Optional supporting text below the heading. */
  description?: ReactNode;
  /** Optional custom dialog body. */
  children?: ReactNode;
  /** Neutral or semantic treatment for the leading icon and continue button. */
  tone?: DialogTone;
  /** Optional icon. A semantic icon is used when omitted. */
  icon?: ReactNode;
  /** Whether to show close and continue, or a single close action. */
  actions?: DialogActions;
  /** Controlled open state. */
  open?: boolean;
  /** Initial uncontrolled open state. */
  defaultOpen?: boolean;
  /** Called whenever the requested open state changes. */
  onOpenChange?: (open: boolean) => void;
  /** Runs before the dialog closes after pressing Continue. */
  onContinue?: () => void;
  /** Runs when the dialog closes from any supported close action. */
  onClose?: () => void;
  /** Visible label for the primary action. */
  continueLabel?: ReactNode;
  /** Visible label for the close action. */
  closeLabel?: ReactNode;
  /** Disables the primary action while custom content is incomplete. */
  continueDisabled?: boolean;
  /** Dialog panel width in pixels. */
  width?: number;
  /** Dialog panel height in pixels. */
  height?: number;
  /** Prevents backdrop and Escape dismissal. The visible Close action remains available. */
  blocking?: boolean;
  /** Additional classes for the dialog panel. */
  className?: string;
}

interface DialogContextValue {
  close: () => void;
}

const DialogContext = createContext<DialogContextValue | null>(null);

const defaultIcons: Record<DialogTone, ReactNode> = {
  neutral: <Info />,
  success: <CircleCheck />,
  warning: <CircleAlert />,
  danger: <CircleX />,
};

const iconClasses: Record<DialogTone, string> = {
  neutral: "bg-[var(--surface-muted)] text-[var(--text)]",
  success: "bg-[var(--success-surface)] text-[var(--success-surface-foreground)]",
  warning: "bg-[var(--warning-surface)] text-[var(--warning-surface-foreground)]",
  danger: "bg-[var(--danger-surface)] text-[var(--danger-surface-foreground)]",
};

const continueTones: Record<DialogTone, "primary" | "success" | "warning" | "danger"> = {
  neutral: "primary",
  success: "success",
  warning: "warning",
  danger: "danger",
};

const DIALOG_WIDTH = 520;
const DIALOG_HEIGHT = 260;
const CLOSE_ONLY_DIALOG_HEIGHT = 236;

interface DialogRect {
  left: number;
  top: number;
  width: number;
  height: number;
}

function subscribeToPortal() {
  return () => undefined;
}

function getFocusableElements(container: HTMLElement) {
  return Array.from(container.querySelectorAll<HTMLElement>(
    'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
  )).filter((element) => !element.hasAttribute("aria-hidden"));
}

export function Dialog({
  trigger,
  title,
  description,
  children,
  tone = "neutral",
  icon,
  actions = "confirm",
  open,
  defaultOpen = false,
  onOpenChange,
  onContinue,
  onClose,
  continueLabel = "Continue",
  closeLabel = "Close",
  continueDisabled = false,
  width: requestedWidth,
  height: requestedHeight,
  blocking = false,
  className,
}: DialogProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const [triggerHidden, setTriggerHidden] = useState(defaultOpen && Boolean(trigger));
  const [hasTriggerOrigin, setHasTriggerOrigin] = useState(false);
  const [surfaceVisible, setSurfaceVisible] = useState(false);
  const [morph, setMorph] = useState<{ from: DialogRect; to: DialogRect }>({
    from: { left: 0, top: 0, width: 1, height: 1 },
    to: { left: 0, top: 0, width: DIALOG_WIDTH, height: DIALOG_HEIGHT },
  });
  const portalContainer = useSyncExternalStore(subscribeToPortal, () => document.body, () => null);
  const triggerRef = useRef<HTMLSpanElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const restoreFocusRef = useRef<HTMLElement | null>(null);
  const titleId = useId();
  const descriptionId = useId();
  const reduceMotion = useReducedMotion() ?? false;
  const expanded = open ?? internalOpen;

  const setExpanded = useCallback((nextOpen: boolean) => {
    if (open === undefined) setInternalOpen(nextOpen);
    onOpenChange?.(nextOpen);
  }, [onOpenChange, open]);

  const close = useCallback(() => {
    setExpanded(false);
    onClose?.();
  }, [onClose, setExpanded]);

  const calculateTargetRect = useCallback((): DialogRect => {
    const width = Math.min(requestedWidth ?? DIALOG_WIDTH, window.innerWidth - 32);
    const height = Math.min(
      requestedHeight ?? (actions === "close" ? CLOSE_ONLY_DIALOG_HEIGHT : DIALOG_HEIGHT),
      window.innerHeight - 32,
    );
    return {
      left: Math.max(16, (window.innerWidth - width) / 2),
      top: Math.max(16, (window.innerHeight - height) / 2),
      width,
      height,
    };
  }, [actions, requestedHeight, requestedWidth]);

  const openDialog = useCallback((event: React.MouseEvent<HTMLSpanElement>) => {
    const source = event.target instanceof HTMLElement
      ? event.target.closest("button, [role='button']") as HTMLElement | null
      : null;
    const sourceRect = (source ?? triggerRef.current)?.getBoundingClientRect();
    const target = calculateTargetRect();

    if (sourceRect) {
      setMorph({
        from: { left: sourceRect.left, top: sourceRect.top, width: sourceRect.width, height: sourceRect.height },
        to: target,
      });
      setHasTriggerOrigin(true);
    } else {
      setMorph({ from: target, to: target });
      setHasTriggerOrigin(false);
    }
    restoreFocusRef.current = source;
    setTriggerHidden(true);
    setSurfaceVisible(true);
    setExpanded(true);
  }, [calculateTargetRect, setExpanded]);

  useEffect(() => {
    if (!expanded || surfaceVisible || !portalContainer) return;
    const frame = requestAnimationFrame(() => {
      const target = calculateTargetRect();
      restoreFocusRef.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
      setMorph({ from: target, to: target });
      setHasTriggerOrigin(false);
      setSurfaceVisible(true);
    });
    return () => cancelAnimationFrame(frame);
  }, [calculateTargetRect, expanded, portalContainer, surfaceVisible]);

  useEffect(() => {
    if (!expanded || !surfaceVisible) return;
    const frame = requestAnimationFrame(() => panelRef.current?.focus({ preventScroll: true }));
    return () => cancelAnimationFrame(frame);
  }, [expanded, surfaceVisible]);

  useEffect(() => {
    if (!expanded) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape" && !blocking) {
        event.preventDefault();
        close();
        return;
      }
      if (event.key !== "Tab" || !panelRef.current) return;
      const focusable = getFocusableElements(panelRef.current);
      if (focusable.length === 0) {
        event.preventDefault();
        panelRef.current.focus();
        return;
      }
      const first = focusable[0];
      const last = focusable.at(-1)!;
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [blocking, close, expanded]);

  const context = useMemo(() => ({ close }), [close]);
  const dialogIcon = icon ?? defaultIcons[tone];

  return (
    <DialogContext.Provider value={context}>
      {trigger ? (
        <span
          ref={triggerRef}
          className={`inline-flex ${expanded || triggerHidden ? "pointer-events-none opacity-0" : "opacity-100"}`}
          onClick={openDialog}
        >
          {trigger}
        </span>
      ) : null}
      {portalContainer ? createPortal(
        <>
          {surfaceVisible ? (
            <motion.button
              type="button"
              aria-label="Close dialog"
              className="fixed inset-0 z-[230] cursor-default bg-black/45 backdrop-blur-[2px]"
              initial={{ opacity: 0 }}
              animate={{ opacity: expanded ? 1 : 0 }}
              transition={reduceMotion ? { duration: 0.1 } : { duration: motionTokens.duration.standard }}
              onClick={blocking ? undefined : close}
              tabIndex={-1}
            />
          ) : null}
          {surfaceVisible ? (
              <motion.div
                ref={panelRef}
                role="dialog"
                aria-modal="true"
                aria-labelledby={titleId}
                aria-describedby={description ? descriptionId : undefined}
                tabIndex={-1}
                className={[
                  "fixed z-[231] box-border overflow-y-auto rounded-[32px] border border-[var(--border)] bg-[var(--surface)] pt-5 px-5 shadow-[var(--shadow-floating)] outline-none",
                  actions === "close" ? "pb-4" : "pb-5",
                  className,
                ].filter(Boolean).join(" ")}
                initial={reduceMotion
                  ? { opacity: 0 }
                  : hasTriggerOrigin
                    ? { opacity: 1, ...morph.from }
                    : { opacity: 0, scale: 0.94, ...morph.to }}
                animate={expanded
                  ? (hasTriggerOrigin
                      ? { opacity: 1, ...morph.to }
                      : { opacity: 1, scale: 1, ...morph.to })
                  : (hasTriggerOrigin
                      ? { opacity: 1, ...morph.from }
                      : { opacity: 0, scale: 0.94, ...morph.to })}
                transition={reduceMotion
                  ? { duration: 0.1 }
                  : hasTriggerOrigin
                    ? motionTokens.spring.morph
                    : motionTokens.spring.smooth}
                onAnimationComplete={() => {
                  if (expanded) return;
                  setSurfaceVisible(false);
                  setTriggerHidden(false);
                  restoreFocusRef.current?.focus({ preventScroll: true });
                }}
              >
                {trigger && hasTriggerOrigin ? (
                  <motion.div
                    aria-hidden="true"
                    {...({ inert: true } as Record<string, unknown>)}
                    className="pointer-events-none absolute inset-0 z-10 grid place-items-center whitespace-nowrap"
                    initial={{ opacity: hasTriggerOrigin ? 1 : 0 }}
                    animate={{ opacity: expanded ? 0 : 1 }}
                    transition={reduceMotion
                      ? { duration: 0.1 }
                      : expanded
                        ? { duration: motionTokens.duration.fast }
                        : { delay: 0.1, duration: motionTokens.duration.standard }}
                  >
                    {trigger}
                  </motion.div>
                ) : null}
                <motion.div
                  className="relative z-20"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: expanded ? 1 : 0 }}
                  transition={reduceMotion
                    ? { duration: 0.1 }
                    : expanded
                      ? { delay: 0.1, duration: motionTokens.duration.standard }
                      : { duration: motionTokens.duration.fast }}
                >
                  <div className="flex flex-col items-center text-center">
                    <span className={`grid size-11 place-items-center rounded-[14px] [&>svg]:size-6 ${iconClasses[tone]}`} aria-hidden="true">
                      {dialogIcon}
                    </span>
                    <div className="mt-3 min-w-0">
                      <h2 id={titleId} className="text-lg font-[700] leading-6 text-[var(--text)]">{title}</h2>
                      {description ? <p id={descriptionId} className="mt-2 text-sm leading-6 text-[var(--text-secondary)]">{description}</p> : null}
                    </div>
                  </div>
                  {children ? <div className="mt-4 text-left">{children}</div> : null}
                  <div className="mt-5 flex items-center justify-center gap-3">
                    {actions === "confirm" ? <Button variant="text" tone="secondary" onClick={close}>{closeLabel}</Button> : null}
                    <Button
                      tone={actions === "confirm" ? continueTones[tone] : "primary"}
                      disabled={continueDisabled}
                      onClick={() => {
                        if (actions === "confirm") onContinue?.();
                        close();
                      }}
                    >
                      {actions === "confirm" ? continueLabel : closeLabel}
                    </Button>
                  </div>
                </motion.div>
              </motion.div>
          ) : null}
        </>,
        portalContainer,
      ) : null}
    </DialogContext.Provider>
  );
}

export function useDialog() {
  const context = useContext(DialogContext);
  if (!context) throw new Error("useDialog must be used inside Dialog.");
  return context;
}
